1	package mevwatch
2	
3	import (
4		"encoding/json"
5		"math"
6		"reflect"
7		"strconv"
8		"strings"
9		"testing"
10	)
11	
12	// incr 命令的解析：合法形式（负号、前导零、边界值）与各类非法增量。
13	func TestKVIncrParseCommands(t *testing.T) {
14		cases := []struct {
15			command    string
16			wantOp     kvOperation
17			wantReason string
18		}{
19			{"incr k=1", kvOperation{isIncr: true, key: "k", delta: 1}, ""},
20			{"incr k=-2", kvOperation{isIncr: true, key: "k", delta: -2}, ""},
21			{"incr k=0", kvOperation{isIncr: true, key: "k", delta: 0}, ""},
22			{"incr k=-0", kvOperation{isIncr: true, key: "k", delta: 0}, ""},  // 负零合法
23			{"incr k=007", kvOperation{isIncr: true, key: "k", delta: 7}, ""}, // 前导零合法
24			{"incr k=-007", kvOperation{isIncr: true, key: "k", delta: -7}, ""},
25			{"incr 键=3", kvOperation{isIncr: true, key: "键", delta: 3}, ""},
26			{"incr k=" + strconv.FormatInt(math.MaxInt64, 10), kvOperation{isIncr: true, key: "k", delta: math.MaxInt64}, ""},
27			{"incr k=" + strconv.FormatInt(math.MinInt64, 10), kvOperation{isIncr: true, key: "k", delta: math.MinInt64}, ""},
28			{"incr", kvOperation{}, ApplyReasonUnknownCommand},     // 没有空格与键
29			{"INCR k=1", kvOperation{}, ApplyReasonUnknownCommand}, // 区分大小写
30			{"Incr k=1", kvOperation{}, ApplyReasonUnknownCommand},
31			{"incr k", kvOperation{}, ApplyReasonIncrMissingEquals}, // 缺等号
32			{"incr =1", kvOperation{}, ApplyReasonEmptyKey},         // 空键
33			{"incr  k=1", kvOperation{}, ApplyReasonKeyHasWhitespace},
34			{"incr k b=1", kvOperation{}, ApplyReasonKeyHasWhitespace},
35			{"incr\tk=1", kvOperation{}, ApplyReasonUnknownCommand}, // 制表符不是普通空格
36			{"incr k=", kvOperation{}, ApplyReasonIncrBadDelta},     // 空增量不是整数
37			{"incr k=+1", kvOperation{}, ApplyReasonIncrBadDelta},   // 不接受正号
38			{"incr k=-", kvOperation{}, ApplyReasonIncrBadDelta},    // 只有负号
39			{"incr k= 1", kvOperation{}, ApplyReasonIncrBadDelta},   // 空白不裁剪
40			{"incr k=1 ", kvOperation{}, ApplyReasonIncrBadDelta},
41			{"incr k=1.0", kvOperation{}, ApplyReasonIncrBadDelta},                  // 小数
42			{"incr k=1e3", kvOperation{}, ApplyReasonIncrBadDelta},                  // 指数
43			{"incr k=١", kvOperation{}, ApplyReasonIncrBadDelta},                    // 非 ASCII 数字
44			{"incr k=1=2", kvOperation{}, ApplyReasonIncrBadDelta},                  // 额外等号属于增量
45			{"incr k=9223372036854775808", kvOperation{}, ApplyReasonIncrBadDelta},  // 超出上限
46			{"incr k=-9223372036854775809", kvOperation{}, ApplyReasonIncrBadDelta}, // 超出下限
47		}
48		for _, tc := range cases {
49			op, reason := parseKVCommand(tc.command)
50			if reason != tc.wantReason {
51				t.Fatalf("parseKVCommand(%q) reason = %q, want %q", tc.command, reason, tc.wantReason)
52			}
53			if tc.wantReason == "" && op != tc.wantOp {
54				t.Fatalf("parseKVCommand(%q) = %+v, want %+v", tc.command, op, tc.wantOp)
55			}
56		}
57	}
58	
59	// 基本语义：键不存在按 0 创建；set 之后累加；delete 之后重新从 0 计；
60	// 结果为规范十进制字符串。
61	func TestKVIncrBasicSemantics(t *testing.T) {
62		out := runKV(t, InitialState{CurrentTerm: 1},
63			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 6,
64				Entries: []LogEntry{
65					entry(1, 1, "incr hits=1"),    // 键不存在：按 0 创建
66					entry(2, 1, "set count=7"),    // 先前写入决定当前值
67					entry(3, 1, "incr count=-2"),  // 7 + (-2) = 5
68					entry(4, 1, "delete count"),   // 删除后
69					entry(5, 1, "incr count=10"),  // 重新从 0 计：10
70					entry(6, 1, "incr hits=-007"), // 1 + (-7) = -6，前导零合法
71				}},
72		)
73		if got := appliedIndexOf(t, out.Results[0]); got != 6 {
74			t.Fatalf("appliedIndex = %d, want 6", got)
75		}
76		if out.Results[0].ApplyError != nil {
77			t.Fatalf("unexpected apply error: %+v", out.Results[0].ApplyError)
78		}
79		kv := finalKVOf(t, out)
80		want := map[string]string{"hits": "-6", "count": "10"}
81		if !reflect.DeepEqual(kv, want) {
82			t.Fatalf("finalKV = %v, want %v", kv, want)
83		}
84	}
85	
86	// 任务示例：set count=7 后应用 incr count=-2，最终 count 为 "5"。
87	func TestKVIncrTaskExample(t *testing.T) {
88		out := runKV(t, InitialState{CurrentTerm: 1},
89			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 2,
90				Entries: []LogEntry{entry(1, 1, "set count=7"), entry(2, 1, "incr count=-2")}},
91		)
92		kv := finalKVOf(t, out)
93		if !reflect.DeepEqual(kv, map[string]string{"count": "5"}) {
94			t.Fatalf("finalKV = %v, want count=5", kv)
95		}
96	}
97	
98	// 规范形式：成功后的值不带前导零，零统一为 "0"；delta 为 0 同样写回规范
99	// 形式并推进应用位置。
100	func TestKVIncrCanonicalForm(t *testing.T) {
101		out := runKV(t, InitialState{CurrentTerm: 1},
102			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 5,
103				Entries: []LogEntry{
104					entry(1, 1, "set a=007"),  // set 按原文保存
105					entry(2, 1, "incr a=0"),   // delta 0：写回规范形式 "7"
106					entry(3, 1, "incr b=000"), // 不存在的键加 0：创建为 "0"
107					entry(4, 1, "set c=-0"),   // 负零当前值
108					entry(5, 1, "incr c=0"),   // 规范化为 "0"
109				}},
110		)
111		if got := appliedIndexOf(t, out.Results[0]); got != 5 {
112			t.Fatalf("appliedIndex = %d, want 5 (zero delta still advances)", got)
113		}
114		kv := finalKVOf(t, out)
115		want := map[string]string{"a": "7", "b": "0", "c": "0"}
116		if !reflect.DeepEqual(kv, want) {
117			t.Fatalf("finalKV = %v, want %v", kv, want)
118		}
119	}
120	
121	// 边界值：int64 上限与下限都能正确表示与累加。
122	func TestKVIncrInt64Boundaries(t *testing.T) {
123		max := strconv.FormatInt(math.MaxInt64, 10)
124		min := strconv.FormatInt(math.MinInt64, 10)
125		out := runKV(t, InitialState{CurrentTerm: 1},
126			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 4,
127				Entries: []LogEntry{
128					entry(1, 1, "incr max="+max),  // 0 + MaxInt64
129					entry(2, 1, "incr min="+min),  // 0 + MinInt64
130					entry(3, 1, "incr max=-"+max), // MaxInt64 - MaxInt64 = 0
131					entry(4, 1, "incr min=1"),     // MinInt64 + 1
132				}},
133		)
134		if out.Results[0].ApplyError != nil {
135			t.Fatalf("unexpected apply error: %+v", out.Results[0].ApplyError)
136		}
137		kv := finalKVOf(t, out)
138		want := map[string]string{
139			"max": "0",
140			"min": strconv.FormatInt(math.MinInt64+1, 10),
141		}
142		if !reflect.DeepEqual(kv, want) {
