242	// 未提交的 incr 不能提前改值或暴露数值错误；重复复制与心跳不重复累加。
243	func TestKVIncrCommitBoundaries(t *testing.T) {
244		out := runKV(t, InitialState{CurrentTerm: 1},
245			// 追加两条 incr 但都不提交：键值表仍为空，非法增量也不暴露。
246			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
247				Entries: []LogEntry{entry(1, 1, "incr k=5"), entry(2, 1, "incr k=oops")}},
248			// 重复复制同一条日志（完全相同，保留），提交位置不变：不累加。
249			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
250				Entries: []LogEntry{entry(1, 1, "incr k=5"), entry(2, 1, "incr k=oops")}},
251			// 心跳提交到 1：只累加一次。
252			AppendRequest{Term: 1, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 1},
253			// 提交位置未前进的心跳：不重复累加。
254			AppendRequest{Term: 1, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 1},
255			// 提交到 2：非法增量此时才报错，应用停在 1。
256			AppendRequest{Term: 1, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 2},
257		)
258		wantApplied := []int{0, 0, 1, 1, 1}
259		for i, result := range out.Results {
260			if !result.Accepted {
261				t.Fatalf("result %d rejected: %s", i, result.Reason)
262			}
263			if got := appliedIndexOf(t, result); got != wantApplied[i] {
264				t.Fatalf("result %d appliedIndex = %d, want %d", i, got, wantApplied[i])
265			}
266		}
267		for i := 0; i < 4; i++ {
268			if out.Results[i].ApplyError != nil {
269				t.Fatalf("result %d unexpected apply error: %+v", i, out.Results[i].ApplyError)
270			}
271		}
272		last := out.Results[4]
273		if last.ApplyError == nil || last.ApplyError.Index != 2 ||
274			last.ApplyError.Reason != ApplyReasonIncrBadDelta {
275			t.Fatalf("result 4 applyError = %+v, want index 2 bad delta", last.ApplyError)
276		}
277		// incr k=5 恰好应用一次。
278		kv := finalKVOf(t, out)
279		if !reflect.DeepEqual(kv, map[string]string{"k": "5"}) {
280			t.Fatalf("finalKV = %v, want k=5 (applied exactly once)", kv)
281		}
282		if *out.FinalAppliedIndex != 1 {
283			t.Fatalf("finalAppliedIndex = %d, want 1", *out.FinalAppliedIndex)
284		}
285	}
286	
287	// 初始已提交前缀中的 incr 照常生效。
288	func TestKVIncrInitialCommittedPrefix(t *testing.T) {
289		initial := InitialState{CurrentTerm: 2, CommittedIndex: 3, Log: []LogEntry{
290			entry(1, 1, "incr k=10"),
